#!/usr/bin/env bash
# Checks that the images built from src/ follow the build context convention in .github/README.md, and that each
# container tool given as an argument sends them the same context. Prints each image's context size.
#
# Usage: check-image-contexts.sh [tool...]   (default: docker podman)
#        check-image-contexts.sh --write     (regenerates src/.dockerignore from the images' allowlists)
set -euo pipefail

repo_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
context_dir="${repo_root}/src"
shared_ignore="${context_dir}/.dockerignore"

# The images built from src/, by Dockerfile relative to src/. Add an image here when you add it to src/.
images=(
  Designer/backend/Migrations.Dockerfile
  Runtime/gateway/Dockerfile
  Runtime/kubernetes-wrapper/src/Dockerfile
  Runtime/localtest/Dockerfile
  Runtime/operator/Dockerfile
  Runtime/operator/Dockerfile.fakes
  Runtime/pdf3/Dockerfile.proxy
  Runtime/pdf3/Dockerfile.worker
  Runtime/workflow-engine/Dockerfile
  Runtime/workflow-engine-app/Dockerfile
)

# A context above these sizes likely sends more than the images need.
max_context_bytes=$((20 * 1024 * 1024))
max_shared_context_bytes=$((64 * 1024 * 1024))

# Prints src/.dockerignore: every path an image's allowlist re-includes, without build output.
shared_dockerignore() {
  echo '# Generated by .github/scripts/check-image-contexts.sh --write. Compose and plain podman builds read this'
  echo "# file instead of an image's own Dockerfile.dockerignore, so it allows what any image built from src/ needs."
  echo '**'
  for image in "${images[@]}"; do
    grep -h '^!' "${context_dir}/${image}.dockerignore" || true
  done | LC_ALL=C sort -u
  printf '%s\n' '**/.DS_Store' '**/.cache' '**/.git' '**/.idea' '**/.vscode' '**/bin' '**/obj' \
    '**/node_modules'
}

if [ "${1:-}" = --write ]; then
  shared_dockerignore >"${shared_ignore}"
  exit 0
fi

if [ "$#" -gt 0 ]; then
  tools=("$@")
else
  tools=(docker podman)
fi

failures=0
fail() {
  echo "::error::$*"
  failures=$((failures + 1))
}

work_dir="$(mktemp -d)"
# The probe must be inside the context, since remote Podman reads a Dockerfile's ignore file only there.
probe_dir="$(mktemp -d "${context_dir}/.image-context-probe.XXXXXX")"
trap 'rm -rf "${work_dir}" "${probe_dir}"' EXIT
printf 'FROM scratch\nCOPY . /ctx/\n' >"${probe_dir}/Dockerfile"

for image in "${images[@]}"; do
  allowlist="${context_dir}/${image}.dockerignore"
  if [ ! -f "${allowlist}" ]; then
    fail "src/${image} has no allowlist. Add src/${image}.dockerignore."
    continue
  fi
  # Podman does not re-include a file through **/ inside a directory that an earlier pattern excluded.
  if grep -nE '^[[:space:]]*!.*\*\*/' "${allowlist}" >"${work_dir}/reincludes"; then
    fail "src/${image}.dockerignore re-includes through **/, which Podman matches differently: $(paste -sd ' ' "${work_dir}/reincludes")"
  fi
done
if [ "${failures}" -gt 0 ]; then
  exit 1
fi

if ! shared_dockerignore | diff -u - "${shared_ignore}" >"${work_dir}/diff" 2>&1; then
  fail "src/.dockerignore is out of date. Run .github/scripts/check-image-contexts.sh --write."
  head -n 40 "${work_dir}/diff"
fi
# Podman would read src/.containerignore before src/.dockerignore, and Compose does not read it at all.
if [ -e "${context_dir}/.containerignore" ]; then
  fail "Remove src/.containerignore. src/.dockerignore is the context's ignore file."
fi

is_podman() {
  "$1" --version 2>/dev/null | grep -qi podman
}

# Writes the files that a tool sends as the context, as "<size> <path>" lines, to the given file. With an allowlist,
# the tool builds the way Docker and devenv do. Without one, it builds the way Compose and plain podman builds do.
list_context() {
  local tool="$1" output="$2" allowlist="${3:-}" tag container
  local args=(build --quiet --file "${probe_dir}/Dockerfile")
  rm -f "${probe_dir}/Dockerfile.dockerignore"
  if [ -n "${allowlist}" ]; then
    cp "${allowlist}" "${probe_dir}/Dockerfile.dockerignore"
    if is_podman "${tool}"; then
      args+=(--ignorefile "${allowlist}")
    fi
  fi
  tag="image-context-probe:$$"
  "${tool}" "${args[@]}" --tag "${tag}" "${context_dir}" >/dev/null
  container="$("${tool}" create "${tag}" probe)"
  mkdir -p "${work_dir}/export"
  "${tool}" export "${container}" | tar -xf - -C "${work_dir}/export" ctx 2>/dev/null || true
  "${tool}" rm "${container}" >/dev/null
  "${tool}" rmi "${tag}" >/dev/null
  if [ -d "${work_dir}/export/ctx" ]; then
    (cd "${work_dir}/export/ctx" && find . ! -type d -printf '%s %P\n' | LC_ALL=C sort -k2) >"${output}"
  else
    : >"${output}"
  fi
  rm -rf "${work_dir}/export"
}

# Prints a listing's row and checks it against the budget and the first tool's listing.
report() {
  local name="$1" tool="$2" listing="$3" first="$4" budget="$5" files bytes
  files="$(wc -l <"${listing}")"
  bytes="$(awk '{ sum += $1 } END { print sum + 0 }' "${listing}")"
  printf '%-45s %-12s %8d %10d\n' "${name}" "$(basename "${tool}")" "${files}" "$((bytes / 1024))"
  if [ "${bytes}" -gt "${budget}" ]; then
    fail "${tool} sends $((bytes / 1024 / 1024)) MiB as the context of ${name}, above the $((budget / 1024 / 1024)) MiB budget."
  fi
  if [ -n "${first}" ] && ! diff -u "${first}" "${listing}" >"${work_dir}/diff"; then
    fail "$(basename "${tools[0]}") and ${tool} send different contexts for ${name}:"
    head -n 40 "${work_dir}/diff"
  fi
}

printf '%-45s %-12s %8s %10s\n' Context Tool Files KiB
first=""
for tool in "${tools[@]}"; do
  listing="${work_dir}/shared-$(basename "${tool}").txt"
  list_context "${tool}" "${listing}"
  report src/.dockerignore "${tool}" "${listing}" "${first}" "${max_shared_context_bytes}"
  first="${first:-${listing}}"
done
shared_listing="${first}"

for image in "${images[@]}"; do
  first=""
  for tool in "${tools[@]}"; do
    listing="${work_dir}/$(basename "${tool}").txt"
    list_context "${tool}" "${listing}" "${context_dir}/${image}.dockerignore"
    report "src/${image}" "${tool}" "${listing}" "${first}" "${max_context_bytes}"
    first="${first:-${listing}}"
  done
  # Compose and plain podman builds get src/.dockerignore's context, so it must hold all that the image needs.
  if missing="$(LC_ALL=C comm -23 <(cut -d' ' -f2- "${first}") <(cut -d' ' -f2- "${shared_listing}"))" &&
    [ -n "${missing}" ]; then
    fail "src/.dockerignore leaves out files that src/${image} needs: $(head -n 10 <<<"${missing}" | paste -sd ' ')"
  fi
done

if [ "${failures}" -gt 0 ]; then
  echo "${failures} problem(s) with the image build contexts. See .github/README.md."
  exit 1
fi
